import { Schema, SchemaKey } from "@formily/json-schema";

type SchemaStep = {
  name: SchemaKey;
  props: any;
  schema: Schema;
};

/**
 * 解析 Schema 模式下的 Steps
 * 借鉴于 https://github.com/alibaba/formily/tree/formily_next/packages/antd/src/form-step/index.tsx
 */
export const parseSchemaSteps = (schema: Schema) => {
  const steps: SchemaStep[] = [];
  schema.mapProperties((schema, name) => {
    if (schema["x-component"]?.indexOf("StepPane") > -1) {
      steps.push({
        name,
        props: schema["x-component-props"],
        schema,
      });
    }
  });
  return steps;
};
